    pesos.inicializarVector(5);
    int[] arr = {10, 3, 5, 7, 2};
    for (int i = 0; i < 5; i++) pesos.agregarElemento(i, arr[i]);

    VectorTDA<Integer> actSol = new Vector<Integer>();
    actSol.inicializarVector(5);
    mochilaExactaRec(pesos, 15, actSol, 0, 0);
}

private static void mochilaExactaRec(VectorTDA<Integer> pesos, int m, VectorTDA<Integer> actSol, int etapa, int actPeso) throws Exception {
    if (actPeso == m) {
        System.out.print("Combinación exacta encontrada: ");
        for (int i = 0; i < etapa; i++) {
            if (actSol.recuperarElemento(i) == 1) {
                System.out.print(pesos.recuperarElemento(i) + " ");
            }
        }
        System.out.println();
        return;
    }
    if (etapa == pesos.capacidadVector()) return;

    int w = pesos.recuperarElemento(etapa);
    // Rama 1: Incluir
    if (actPeso + w <= m) {
        actSol.agregarElemento(etapa, 1);
        mochilaExactaRec(pesos, m, actSol, etapa + 1, actPeso + w);
    }
    // Rama 0: No incluir
    actSol.agregarElemento(etapa, 0);
    mochilaExactaRec(pesos, m, actSol, etapa + 1, actPeso);
}

public static void resolverPermutacionesASCII() throws Exception {
    VectorTDA<Character> p = new Vector<Character>();
    p.inicializarVector(4);
    VectorTDA<Boolean> usados = new Vector<Boolean>();
    usados.inicializarVector(4);
    for (int i = 0; i < 4; i++) usados.agregarElemento(i, false);

    char[] letras = {'A', 'B', 'C', 'D'};
    permutacionesAsciiRec(p, usados, letras, 0);
