private static void permutacionesAsciiRec(VectorTDA<Character> p, VectorTDA<Boolean> usados, char[] letras, int etapa) throws Exception {
    if (etapa == 4) {
        System.out.println("" + p.recuperarElemento(0) + p.recuperarElemento(1) + p.recuperarElemento(2) + p.recuperarElemento(3));
        return;
    }
    for (int i = 0; i < 4; i++) {
        if (!usados.recuperarElemento(i)) {
            char c = letras[i];
            if (etapa == 0 || Math.abs(c - p.recuperarElemento(etapa - 1)) >= 2) {
                usados.agregarElemento(i, true);
                p.agregarElemento(etapa, c);
                permutacionesAsciiRec(p, usados, letras, etapa + 1);
                usados.agregarElemento(i, false);
            }
        }
    }
}

public static void colorearGrafo2Colores(GrafoTDA<Integer> g, int n) throws Exception {
    VectorTDA<Integer> colores = new Vector<Integer>();
    colores.inicializarVector(n);
    for (int i = 0; i < n; i++) colores.agregarElemento(i, -1); // -1 = sin color

    if (colorearRec(g, 0, n, colores)) {
        for (int i = 0; i < n; i++) {
            System.out.println("Vértice " + i + ": " + (colores.recuperarElemento(i) == 0 ? "ROJO" : "NEGRO"));
        }
    } else {
        System.out.println("El grafo no es 2-coloreable (no es bipartito)");
    }
}

private static boolean colorearRec(GrafoTDA<Integer> g, int v, int n, VectorTDA<Integer> colores) throws Exception {
    if (v == n) return true;
    for (int c = 0; c <= 1; c++) {
        if (colorValido(g, v, c, colores)) {
            colores.agregarElemento(v, c);
            if (colorearRec(g, v + 1, n, colores)) return true;
            colores.agregarElemento(v, -1);
        }
    }
    return false;
}

private static boolean colorValido(GrafoTDA<Integer> g, int v, int c, VectorTDA<Integer> colores) throws Exception {
    ConjuntoTDA<Integer> ady = g.Adyacentes(v);
    while (!ady.conjuntoVacio()) {
        int u = ady.elegir();
        ady.sacar(u);
        if (colores.recuperarElemento(u) == c) return false;
    }
    return true;
}

public class EstrategiaGreedyCorchos {
    public static void planificarJuego(int n) {
        int resto = n % 4;
        if (resto == 1) {
            System.out.println("Eleccion: Jugar SEGUNDO. El estado inicial " + n + " es NODO P.");
        } else {
            int jugadaInicial = (resto == 0) ? 3 : (resto - 1);
            System.out.println("Eleccion: Jugar PRIMERO. El estado inicial " + n + " es NODO N.");
            System.out.println("Movida inicial: Retirar " + jugadaInicial + " corchos, dejando " + (n - jugadaInicial) + " (Nodo P).");
        }
    }

    public static int responderMovidaRival(int corchosRetiradosPorRival) {
        // Invariante complementaria: la suma de cada ronda jugador+rival es exactamente 4
        return 4 - corchosRetiradosPorRival;
    }
}

