public static boolean encontrarCicloHamiltoniano(GrafoTDA<Integer> g, int n) throws Exception {
    VectorTDA<Integer> camino = new Vector<Integer>();
    camino.inicializarVector(n);
    VectorTDA<Boolean> visitados = new Vector<Boolean>();
    visitados.inicializarVector(n);
    for (int i = 0; i < n; i++) visitados.agregarElemento(i, false);

    // Fijar vértice inicial 0 (A) para romper simetrías cíclicas
    camino.agregarElemento(0, 0);
    visitados.agregarElemento(0, true);

    return hamiltonianoRec(g, camino, 1, visitados, n);
}

private static boolean hamiltonianoRec(GrafoTDA<Integer> g, VectorTDA<Integer> camino, int etapa, VectorTDA<Boolean> visitados, int n) throws Exception {
    if (etapa == n) {
        int ultimo = camino.recuperarElemento(n - 1);
        int primero = camino.recuperarElemento(0);
        if (g.ExisteArista(ultimo, primero)) {
            System.out.print("Ciclo Hamiltoniano hallado: ");
            for (int i = 0; i < n; i++) {
                System.out.print(camino.recuperarElemento(i) + " -> ");
            }
            System.out.println(primero);
            return true;
        }
        return false;
    }

    int anterior = camino.recuperarElemento(etapa - 1);
    ConjuntoTDA<Integer> ady = g.Adyacentes(anterior);
    while (!ady.conjuntoVacio()) {
        int w = ady.elegir();
        ady.sacar(w);
        if (!visitados.recuperarElemento(w)) {
            visitados.agregarElemento(w, true);
            camino.agregarElemento(etapa, w);
            if (hamiltonianoRec(g, camino, etapa + 1, visitados, n)) return true;
            visitados.agregarElemento(w, false); // Vuelta atrás
        }
    }
    return false;
}

