public static VectorTDA<Integer> maximoCaminoSalas(GrafoDirTDA<Integer> g, int n) throws Exception {
    VectorTDA<Integer> caminoActual = new Vector<Integer>();
    caminoActual.inicializarVector(n + 1);
    VectorTDA<Integer> mejorCamino = new Vector<Integer>();
    mejorCamino.inicializarVector(n + 1);

    caminoActual.agregarElemento(0, 0); // Comienza en la sala 0
    int[] maxSalas = new int[]{-1};

    maxSalasRec(g, 0, n, caminoActual, 1, mejorCamino, maxSalas);
    return mejorCamino;
}

private static void maxSalasRec(GrafoDirTDA<Integer> g, int actual, int n, VectorTDA<Integer> caminoActual, int etapa, VectorTDA<Integer> mejorCamino, int[] maxSalas) throws Exception {
    if (actual == n) {
        if (etapa > maxSalas[0]) {
            maxSalas[0] = etapa;
            for (int i = 0; i < etapa; i++) {
                mejorCamino.agregarElemento(i, caminoActual.recuperarElemento(i));
            }
        }
        return;
    }

    // Poda de cota superior: incluso si pasara por todas las salas restantes entre actual y n
    if (etapa + (n - actual) <= maxSalas[0]) {
        return;
    }

    ConjuntoTDA<Integer> ady = g.Adyacentes(actual);
    while (!ady.conjuntoVacio()) {
        int sig = ady.elegir();
        ady.sacar(sig);
        if (sig > actual) { // Garantizado por topología de salas
            caminoActual.agregarElemento(etapa, sig);
            maxSalasRec(g, sig, n, caminoActual, etapa + 1, mejorCamino, maxSalas);
        }
    }
}

