public static VectorTDA<Integer> recorridoReyMinimo(MatrizTDA<Integer> tablero, int n, int x0, int y0) throws Exception {
    int totalCasillas = n * n;
    VectorTDA<Integer> mejorCamino = new Vector<Integer>();
    mejorCamino.inicializarVector(totalCasillas);

    VectorTDA<Integer> caminoActual = new Vector<Integer>();
    caminoActual.inicializarVector(totalCasillas);

    MatrizTDA<Boolean> visitado = new Matriz<Boolean>();
    visitado.inicializarMatriz(n);
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            visitado.setearValor(i, j, false);
        }
    }

    visitado.setearValor(x0, y0, true);
    caminoActual.agregarElemento(0, x0 * n + y0);

    int[] mejorCosto = new int[]{Integer.MAX_VALUE};
    recorrerReyRec(tablero, n, x0, y0, 1, 0, caminoActual, visitado, mejorCamino, mejorCosto);
    return mejorCamino;
}

private static void recorrerReyRec(MatrizTDA<Integer> tablero, int n, int x, int y, int etapa, int actCosto, VectorTDA<Integer> caminoActual, MatrizTDA<Boolean> visitado, VectorTDA<Integer> mejorCamino, int[] mejorCosto) throws Exception {
    int totalCasillas = n * n;
    if (etapa == totalCasillas) {
        if (actCosto < mejorCosto[0]) {
            mejorCosto[0] = actCosto;
            for (int i = 0; i < totalCasillas; i++) {
                mejorCamino.agregarElemento(i, caminoActual.recuperarElemento(i));
            }
        }
        return;
    }

    // Poda por cota inferior (Lower Bound)
    int cotaInferior = calcularCotaInferiorRey(tablero, n, visitado, etapa);
    if (actCosto + cotaInferior >= mejorCosto[0]) {
        return; // PODA
    }

    int[] dx = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dy = {-1, 0, 1, -1, 1, -1, 0, 1};

    for (int dir = 0; dir < 8; dir++) {
        int nx = x + dx[dir];
        int ny = y + dy[dir];
        if (nx >= 0 && nx < n && ny >= 0 && ny < n && !visitado.obtenerValor(nx, ny)) {
            int pesoPaso = etapa * tablero.obtenerValor(nx, ny);
            visitado.setearValor(nx, ny, true);
            caminoActual.agregarElemento(etapa, nx * n + ny);

            recorrerReyRec(tablero, n, nx, ny, etapa + 1, actCosto + pesoPaso, caminoActual, visitado, mejorCamino, mejorCosto);

            visitado.setearValor(nx, ny, false); // Vuelta atrás
        }
    }
}

private static int calcularCotaInferiorRey(MatrizTDA<Integer> tablero, int n, MatrizTDA<Boolean> visitado, int etapa) throws Exception {
    // Cota inferior voraz: asignar los pesos menores libres a los instantes cronológicos inmediatos
    // Para simplificar, acumulamos el peso mínimo global libre multiplicado por la suma de pasos restantes
    int minPesoLibre = Integer.MAX_VALUE;
    int libres = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (!visitado.obtenerValor(i, j)) {
                libres++;
                int p = tablero.obtenerValor(i, j);
                if (p < minPesoLibre) {
                    minPesoLibre = p;
                }
            }
        }
    }
    if (libres == 0) return 0;
    // Suma de progresión aritmética de pasos: sum_{i=etapa}^{n*n - 1} i
    int totalCasillas = n * n;
    int sumaPasos = ((totalCasillas - 1 + etapa) * libres) / 2;
    return minPesoLibre * sumaPasos;
}

