private static void generarSubconjuntosRec(int k, VectorTDA<Integer> u, int etapa) throws Exception {
    if (etapa == k) {
        System.out.print("{ ");
        for (int i = 0; i < k; i++) {
            if (u.recuperarElemento(i) == 1) {
                System.out.print((i + 1) + " ");
            }
        }
        System.out.println("}");
        return;
