    // Rama 0: No incluir el elemento
    u.agregarElemento(etapa, 0);
    generarSubconjuntosRec(k, u, etapa + 1);
    // Rama 1: Incluir el elemento
    u.agregarElemento(etapa, 1);
    generarSubconjuntosRec(k, u, etapa + 1);
}

public static void enumerarCaminosSimples(GrafoDirTDA<Integer> g, int s, int cantVertices) throws Exception {
    VectorTDA<Integer> camino = new Vector<Integer>();
    camino.inicializarVector(cantVertices);
    VectorTDA<Boolean> visitado = new Vector<Boolean>();
    visitado.inicializarVector(cantVertices);
    for (int i = 0; i < cantVertices; i++) {
        visitado.agregarElemento(i, false);
    }

    camino.agregarElemento(0, s);
    visitado.agregarElemento(s, true);
    caminosRec(g, s, camino, visitado, 1, cantVertices);
}

private static void caminosRec(GrafoDirTDA<Integer> g, int actual, VectorTDA<Integer> camino, VectorTDA<Boolean> visitado, int etapa, int totalVertices) throws Exception {
    // Cada camino parcial construido es en sí mismo un camino simple válido
    imprimirCamino(camino, etapa);

    ConjuntoTDA<Integer> ady = g.Adyacentes(actual);
    while (!ady.conjuntoVacio()) {
        int w = ady.elegir();
        ady.sacar(w);
        if (!visitado.recuperarElemento(w)) {
            visitado.agregarElemento(w, true);
            camino.agregarElemento(etapa, w);
            caminosRec(g, w, camino, visitado, etapa + 1, totalVertices);
            visitado.agregarElemento(w, false); // Vuelta atrás
        }
    }
}

private static void imprimirCamino(VectorTDA<Integer> c, int len) throws Exception {
