        System.out.print(c.recuperarElemento(i) + (i < len - 1 ? " -> " : ""));
    }
    System.out.println();
}

public class NimMinimaxSolver {
    public static final int MAX = 1;
    public static final int MIN = -1;

    // Resolucion analitica por Teorema de Bouton (O(k))
    public static boolean esGanadorTurno(int[] pilas) {
        int xorSum = 0;
        for (int p : pilas) xorSum ^= p;
        return xorSum != 0;
    }

    // Resolucion por Minimax con Backtracking sobre VectorTDA
    public static int minimaxNim(int[] pilas, int turno, int alfa, int beta) {
        boolean hayMovidas = false;
        int mejorVal = (turno == MAX) ? -1 : 1;

        for (int i = 0; i < pilas.length; i++) {
            if (pilas[i] > 0) {
                hayMovidas = true;
                int cantOriginal = pilas[i];
                for (int c = 1; c <= cantOriginal; c++) {
                    pilas[i] -= c; // Transicion
                    int val = minimaxNim(pilas, -turno, alfa, beta);
                    pilas[i] = cantOriginal; // Backtracking

                    if (turno == MAX) {
                        mejorVal = Math.max(mejorVal, val);
                        alfa = Math.max(alfa, mejorVal);
                    } else {
                        mejorVal = Math.min(mejorVal, val);
                        beta = Math.min(beta, mejorVal);
                    }
                    if (beta <= alfa) break;
                }
            }
            if (beta <= alfa) break;
        }

        if (!hayMovidas) {
            // Regla normal: quien no puede mover pierde (el anterior retiro el ultimo y gano)
            return -turno;
        }
        return mejorVal;
    }
}

import java.util.*;

public class JuegoGrundySolver {
    private static Map<Integer, Integer> memo = new HashMap<>();

    public static int grundy(int n) {
        if (n <= 2) return 0; // 1 y 2 no se pueden dividir en partes desiguales
        if (memo.containsKey(n)) return memo.get(n);

        Set<Integer> sucesores = new HashSet<>();
        for (int a = 1; a < n - a; a++) {
            int b = n - a;
            sucesores.add(grundy(a) ^ grundy(b));
        }

        int mex = 0;
        while (sucesores.contains(mex)) mex++;
        memo.put(n, mex);
        return mex;
    }

    public static void clasificar(int n) {
        int g = grundy(n);
        System.out.println("n = " + n + " -> Grundy = " + g + " -> " + (g > 0 ? "NODO N (Gana MAX)" : "NODO P (Gana MIN)"));
    }

    public static void main(String[] args) {
