        // G(1)=0, G(2)=0, G(3)=1, G(4)=0, G(5)=2, G(6)=1, G(7)=0, G(8)=2, G(9)=1, G(10)=0
        clasificar(8);  // G(8)=2 -> Nodo N (Gana el primer jugador)
        clasificar(9);  // G(9)=1 -> Nodo N (Gana el primer jugador)
