import java.util.*;

public class ToadsAndFrogsSolver {
    public static final int ALICIA_RANAS = 1; // Mueve 'R' a la derecha
    public static final int BRUNO_SAPOS = -1; // Mueve 'S' a la izquierda

    static class Movida {
        int origen, destino;
        Movida(int o, int d) { origen = o; destino = d; }
    }

    public static int resolver(char[] b, int turno, int alfa, int beta, int[] contadorNodos) {
        contadorNodos[0]++;
        List<Movida> movidas = obtenerMovidas(b, turno);
        if (movidas.isEmpty()) {
            return -turno; // Pierde el de turno
        }

        int mejor = (turno == ALICIA_RANAS) ? -100 : 100;
        for (Movida m : movidas) {
            // Aplicar jugada
            b[m.destino] = b[m.origen];
            b[m.origen] = '_';

            int val = resolver(b, -turno, alfa, beta, contadorNodos);

            // Backtracking
            b[m.origen] = b[m.destino];
            b[m.destino] = '_';

            if (turno == ALICIA_RANAS) {
                mejor = Math.max(mejor, val);
                alfa = Math.max(alfa, val);
            } else {
                mejor = Math.min(mejor, val);
                beta = Math.min(beta, val);
            }
            if (beta <= alfa) break; // Poda Alfa-Beta
        }
        return mejor;
    }

    public static List<Movida> obtenerMovidas(char[] b, int turno) {
        List<Movida> lista = new ArrayList<>();
        int n = b.length;
        if (turno == ALICIA_RANAS) {
            for (int i = 0; i < n; i++) {
                if (b[i] == 'R') {
                    if (i + 1 < n && b[i + 1] == '_') lista.add(new Movida(i, i + 1));
                    if (i + 2 < n && b[i + 1] == 'S' && b[i + 2] == '_') lista.add(new Movida(i, i + 2));
                }
            }
        } else {
            for (int i = 0; i < n; i++) {
                if (b[i] == 'S') {
                    if (i - 1 >= 0 && b[i - 1] == '_') lista.add(new Movida(i, i - 1));
                    if (i - 2 >= 0 && b[i - 1] == 'R' && b[i - 2] == '_') lista.add(new Movida(i, i - 2));
                }
            }
        }
        return lista;
    }
}

