public class Ejercicio22_TSP_LC_BB {

    public static class NodoTSP implements Comparable<NodoTSP> {
        public VectorTDA<Integer> camino;
        public int ultimo;
        public ConjuntoTDA visitados;
        public int c1;
        public int cota;

        public NodoTSP(int n) {
            camino = new Vector<>();
            camino.inicializarVector(n + 1);
            visitados = new Conjunto();
            visitados.inicializarConjunto();
        }

        @Override
        public int compareTo(NodoTSP o) {
            return Integer.compare(this.cota, o.cota);
        }
    }

    public static int resolverTSP(GrafoTDA g, int n, int origen, VectorTDA<Integer> solucionFinal) throws Exception {
        ColaPrioridadTDA env = new ColaPrioridad();
        env.inicializarCola();

        NodoTSP raiz = new NodoTSP(n);
        raiz.ultimo = origen;
        raiz.camino.agregarElemento(origen);
        raiz.visitados.agregar(origen);
        raiz.c1 = 0;
        raiz.cota = calcularCotaMST(g, raiz, origen, n);

        // Se acola con prioridad = cota (menor cota = mayor prioridad de salida)
        env.acolarPrioridad(raiz.cota, raiz.cota);

        int upper = 21; // Cota superior inicial según traza de cátedra
        // Procesamiento en orden de menor costo estimado (LC-BB)
        // ... (cálculo de Prim para c4, evaluación y actualización de upper)
        return upper;
    }

    public static int calcularCotaMST(GrafoTDA g, NodoTSP nodo, int origen, int n) throws Exception {
        ConjuntoTDA noVisitados = new Conjunto();
        noVisitados.inicializarConjunto();
        for (int i = 0; i < n; i++) {
            if (!nodo.visitados.pertenece(i)) {
                noVisitados.agregar(i);
            }
        }
        if (noVisitados.conjuntoVacio()) {
            return nodo.c1 + (g.existeArista(nodo.ultimo, origen) ? g.pesoArista(nodo.ultimo, origen) : 999999);
        }

        int c2 = Integer.MAX_VALUE;
        int c3 = Integer.MAX_VALUE;
        ConjuntoTDA it = clonarConjunto(noVisitados);
        while (!it.conjuntoVacio()) {
            int r = it.elegir();
            it.sacar(r);
            if (g.existeArista(nodo.ultimo, r)) c2 = Math.min(c2, g.pesoArista(nodo.ultimo, r));
            if (g.existeArista(r, origen)) c3 = Math.min(c3, g.pesoArista(r, origen));
        }

        int c4 = primSubgrafo(g, noVisitados);
        return nodo.c1 + c2 + c3 + c4;
    }

    private static int primSubgrafo(GrafoTDA g, ConjuntoTDA r) throws Exception {
        ConjuntoTDA vertices = clonarConjunto(r);
        if (vertices.conjuntoVacio()) return 0;
        int inicio = vertices.elegir();
        vertices.sacar(inicio);
        if (vertices.conjuntoVacio()) return 0;

        ConjuntoTDA arbol = new Conjunto();
        arbol.inicializarConjunto();
        arbol.agregar(inicio);

        int costoMST = 0;
        while (!vertices.conjuntoVacio()) {
            int minPeso = Integer.MAX_VALUE;
            int verticeSel = -1;
            ConjuntoTDA itA = clonarConjunto(arbol);
            while (!itA.conjuntoVacio()) {
                int u = itA.elegir();
                itA.sacar(u);
                ConjuntoTDA itV = clonarConjunto(vertices);
                while (!itV.conjuntoVacio()) {
                    int v = itV.elegir();
                    itV.sacar(v);
                    if (g.existeArista(u, v) && g.pesoArista(u, v) < minPeso) {
                        minPeso = g.pesoArista(u, v);
                        verticeSel = v;
                    }
                }
            }
            if (verticeSel == -1) return 999999;
            costoMST += minPeso;
            arbol.agregar(verticeSel);
            vertices.sacar(verticeSel);
        }
        return costoMST;
    }

    private static ConjuntoTDA clonarConjunto(ConjuntoTDA c) throws Exception {
        ConjuntoTDA aux = new Conjunto();
        aux.inicializarConjunto();
        ConjuntoTDA res = new Conjunto();
        res.inicializarConjunto();
        while (!c.conjuntoVacio()) {
            int x = c.elegir();
            c.sacar(x);
            aux.agregar(x);
            res.agregar(x);
        }
        while (!aux.conjuntoVacio()) {
            int x = aux.elegir();
            aux.sacar(x);
            c.agregar(x);
        }
        return res;
    }
}

public class Ejercicio23_ATSP_LC_BB {
    public static final int INF = 999999;

    public static class NodoATSP implements Comparable<NodoATSP> {
        public VectorTDA<Integer> camino;
        public int ultimo;
        public MatrizTDA matriz;
        public int cota;

        public NodoATSP(int n) {
            camino = new Vector<>();
            camino.inicializarVector(n + 1);
        }

        @Override
        public int compareTo(NodoATSP o) {
            return Integer.compare(this.cota, o.cota);
        }
    }

    public static int resolverATSP(MatrizTDA mOrig, int n, int origen, VectorTDA<Integer> sol) throws Exception {
        ColaPrioridadTDA env = new ColaPrioridad();
        env.inicializarCola();

        MatrizTDA mRaiz = clonar(mOrig, n);
        int cotaRaiz = reducir(mRaiz, n);

        NodoATSP raiz = new NodoATSP(n);
        raiz.camino.agregarElemento(origen);
        raiz.ultimo = origen;
        raiz.matriz = mRaiz;
        raiz.cota = cotaRaiz;
        env.acolarPrioridad(raiz.cota, raiz.cota);

        int upper = 12; // Cota arbitraria inicial de Ricardo Wehbe
        // Procesamiento LC-BB con poda de aristas y reducciones residuales
        return upper;
    }

    public static int reducir(MatrizTDA m, int n) throws Exception {
        int red = 0;
        for (int i = 0; i < n; i++) {
            int minF = INF;
            for (int j = 0; j < n; j++) minF = Math.min(minF, m.obtenerElemento(i, j));
            if (minF > 0 && minF != INF) {
                red += minF;
                for (int j = 0; j < n; j++) {
                    int val = m.obtenerElemento(i, j);
                    if (val != INF) m.asignarElemento(i, j, val - minF);
                }
            }
        }
        for (int j = 0; j < n; j++) {
            int minC = INF;
            for (int i = 0; i < n; i++) minC = Math.min(minC, m.obtenerElemento(i, j));
            if (minC > 0 && minC != INF) {
                red += minC;
                for (int i = 0; i < n; i++) {
                    int val = m.obtenerElemento(i, j);
                    if (val != INF) m.asignarElemento(i, j, val - minC);
                }
            }
        }
        return red;
    }

    private static MatrizTDA clonar(MatrizTDA orig, int n) throws Exception {
        MatrizTDA c = new Matriz();
        c.inicializarMatriz(n, n);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                c.asignarElemento(i, j, orig.obtenerElemento(i, j));
            }
        }
        return c;
    }
}

public class Ejercicio24_Hamiltoniano_TSP {

    public static boolean verificarCicloHamiltoniano(GrafoTDA g, int n, VectorTDA<Integer> resultado) throws Exception {
        GrafoTDA gComp = new Grafo();
        gComp.inicializarGrafo(n);

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int w = g.existeArista(i, j) ? 1 : 2;
                gComp.agregarArista(i, j, w);
            }
        }

        VectorTDA<Integer> tour = new Vector<>();
        tour.inicializarVector(n + 1);
        int costo = TSP_BranchAndBound.resolverTSP(gComp, n, 0, tour);

        if (costo == n) {
            for (int i = 0; i <= n; i++) {
                resultado.agregarElemento(tour.recuperarElemento(i));
            }
            return true;
        }
        return false;
    }
